import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2017-MAR-29 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAR-29 :: Ceph Performance Weekly","date":"2017-04-06T00:00:00.000Z","updated":"2017-04-07T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","性能优化","编码优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAR-29_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAR-29_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),n={name:"posts/2017/2017-MAR-29_-_-_Ceph_Performance_Weekly.md"};function s(i,e,_,a,p,g){return r(),o("div",null,[...e[0]||(e[0]=[l("<p>本次会议主要讨论了Ceph分布式存储项目的进展和优化方案。以下是会议的关键内容：</p><p><strong>项目进展</strong>：</p><ol><li><strong>Boost请求优化</strong>：Igor最近实现了Blob重用和扩展，对性能有显著提升。同时，正在进行内存利用率和内存分配器的改进。</li><li><strong>缓存优化</strong>：Bluestar正在进行缓存优化测试，目前效果良好。</li><li><strong>运行到完成分支</strong>：计划基于新功能实现运行到完成分支，以提高墙设备性能。</li><li><strong>编码优化</strong>：对Barrington编码进行了优化，性能提升明显。讨论了使用前几位字节表示数据长度的优化方案，但需要格式更改。</li><li><strong>Crush布局优化</strong>：讨论了Crush布局优化和显式映射功能，这将进一步提高Ceph的性能和可扩展性。</li></ol><p><strong>讨论议题</strong>：</p><ol><li><strong>Barrington编码优化</strong>：讨论了优化Barrington编码的方案，包括使用前几位字节表示数据长度。</li><li><strong>编码优化方案</strong>：讨论了将所有编码方式进行统一优化，以提高代码可读性和可维护性。</li><li><strong>运行到完成分支</strong>：讨论了运行到完成分支的实现和测试方案。</li></ol><p><strong>决定事项</strong>：</p><ol><li>对Barrington编码进行优化，并提交相关Pull Request。</li><li>计划对其他编码方式进行类似优化。</li><li>计划对运行到完成分支进行测试和验证。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Bluestar继续进行缓存优化测试。</li><li>Andrey完成运行到完成分支的实现和测试。</li><li>Nick提交Barrington编码优化Pull Request。</li><li>对其他编码方式进行优化。</li></ol><p>本次会议强调了性能优化和编码优化在Ceph项目中的重要性，并明确了后续的行动计划，以进一步提高Ceph的性能和可维护性。</p>",10)])])}const C=t(n,[["render",s]]);export{d as __pageData,C as default};
